      clave: [['Validación', 'Comprobación de que el programa cumple la tarea con seguridad'], ['Colisión', 'Choque del robot o su efector con algo de la celda'], ['Tiempo de ciclo', 'Tiempo de una repetición completa de la tarea'], ['Ajuste fino', 'Corrección pequeña de puntos o tiempos en la celda real'], ['Bitácora', 'Registro de pruebas, cambios y resultados']],
