      preguntas: [['¿Qué se comprueba en el simulador?', 'Alcance de los puntos, colisiones y tiempo de ciclo.'], ['¿Qué licencia tiene Webots?', 'Es gratuito y de código abierto, con licencia Apache 2.0.'], ['¿En qué orden se valida en físico?', 'Velocidad baja sin pieza, luego con pieza y al final a velocidad de trabajo.'], ['¿Cómo mides la repetibilidad de tu brazo?', 'Marcando dónde deja la pieza en 10 repeticiones y midiendo la mayor diferencia.']],
      errores: ['Cambiar varias cosas a la vez.', 'Probar a velocidad de trabajo un punto nuevo.', 'Creer que lo simulado sale igual en físico.', 'No registrar los cambios.'],
