  /* =================== BANCO DE PREGUNTAS =================== */
  const RAD = Math.PI / 180;
  const gen = {
    m4cinem: rnd => { const L1 = pick(rnd, [60, 80, 100, 120]), L2 = pick(rnd, [60, 80, 100]), t1 = pick(rnd, [0, 30, 45, 60, 90]), t2 = pick(rnd, [0, 30, 45, 60, 90, -30, -45]);
      const P = (a, b) => 'x = ' + f(a, 1) + ' mm · y = ' + f(b, 1) + ' mm', x = L1 * Math.cos(t1 * RAD) + L2 * Math.cos((t1 + t2) * RAD), y = L1 * Math.sin(t1 * RAD) + L2 * Math.sin((t1 + t2) * RAD);
      const xa = L1 * Math.cos(t1 * RAD) + L2 * Math.cos(t2 * RAD), ya = L1 * Math.sin(t1 * RAD) + L2 * Math.sin(t2 * RAD);
      return { q: 'Un brazo plano tiene L1 = ' + L1 + ' mm y L2 = ' + L2 + ' mm. Con θ1 = ' + t1 + '° y θ2 = ' + t2 + '° (θ2 medido desde el primer eslabón), ¿dónde queda la punta?', op: ops(P(x, y), [P(xa, ya), P(y, x), P(L1 + L2, 0)], [P(x, -y), P(x + 10, y), P(L1 * Math.cos(t1 * RAD), L1 * Math.sin(t1 * RAD))]), r: 'x = ' + L1 + ' cos ' + t1 + '° + ' + L2 + ' cos ' + (t1 + t2) + '° = ' + f(x, 1) + ' mm; y = ' + L1 + ' sen ' + t1 + '° + ' + L2 + ' sen ' + (t1 + t2) + '° = ' + f(y, 1) + ' mm.' }; },
    m4paletiza: rnd => { const cols = pick(rnd, [2, 3, 4]), rows = pick(rnd, [2, 3]), x0 = pick(rnd, [60, 80, 90, 100, 120]), y0 = pick(rnd, [-60, -40, -30, 0, 20]), dx = pick(rnd, [25, 30, 35, 40]), dy = pick(rnd, [25, 30, 40, 50]), k = 2 + Math.floor(rnd() * (cols * rows - 1)), n = k - 1, fi = Math.floor(n / cols), co = n % cols;
      const P = (a, b) => 'X' + a + ' Y' + b, nb = k, fb = Math.floor(nb / cols), cb = nb % cols;
      return { q: 'Un robot acomoda piezas en una charola de ' + rows + ' filas × ' + cols + ' columnas, llenando fila por fila. La primera pieza va en X' + x0 + ' Y' + y0 + ' (mm) y la separación es dx = ' + dx + ' mm y dy = ' + dy + ' mm. ¿Dónde va la pieza número ' + k + ' (contando desde 1)?', op: ops(P(x0 + co * dx, y0 + fi * dy), [P(x0 + cb * dx, y0 + fb * dy), P(x0 + fi * dx, y0 + co * dy), P(x0 + n * dx, y0)], [P(x0 + co * dy, y0 + fi * dx), P(x0 + (co + 1) * dx, y0 + (fi + 1) * dy), P(x0 + co * dx, y0 + (fi + 1) * dy)]), r: 'Índice desde 0: n = ' + n + '; fila = ' + n + ' ÷ ' + cols + ' = ' + fi + ', columna = ' + n + ' mod ' + cols + ' = ' + co + '; X = ' + x0 + ' + ' + co + ' × ' + dx + ' = ' + (x0 + co * dx) + ', Y = ' + y0 + ' + ' + fi + ' × ' + dy + ' = ' + (y0 + fi * dy) + '.' }; },
    m4agarre: rnd => { const g = pick(rnd, [20, 50, 80, 100, 150, 200, 300]), mu = pick(rnd, [0.3, 0.4, 0.5, 0.6]), S = pick(rnd, [2, 3]), m = g / 1000, F = m * 9.81 * S / (mu * 2), N = x => f(x, 2) + ' N';
      return { q: 'Una pinza de dos dedos (n = 2) sostiene por fricción una pieza de ' + g + ' g. Con μ = ' + f(mu, 1) + ' y factor de seguridad S = ' + S + ', ¿qué fuerza debe apretar cada dedo?', op: ops(N(F), [N(m * 9.81 / (mu * 2)), N(m * 9.81 * S / mu), N(m * 9.81 * S * mu / 2)], [N(g * 9.81 * S / (mu * 2)), N(F * 2), N(m * S / (mu * 2))]), r: 'F = m × g × S / (μ × n) = ' + f(m, 3) + ' × 9.81 × ' + S + ' / (' + f(mu, 1) + ' × 2) = ' + N(F) + '.' }; },
    m4par: rnd => { const g = pick(rnd, [30, 40, 50, 60, 80, 100, 120]), d = pick(rnd, [8, 10, 12, 14, 16, 18, 20]), kc = g / 1000 * d, Nm = kc * 0.0981, T = (a, b) => f(a, 2) + ' kg·cm (' + f(b, 3) + ' N·m)';
      return { q: 'Con el brazo horizontal, una carga de ' + g + ' g queda a ' + d + ' cm del eje del hombro. ¿Qué par necesita el servo solo para esa carga?', op: ops(T(kc, Nm), [T(g * d, g * d * 0.0981), T(g / 1000 / d, g / 1000 / d * 0.0981), T(kc * 9.81, kc * 9.81 * 0.0981)], [T(kc / 2, Nm / 2), T(kc * 2, Nm * 2)]), r: 'τ = m × d = ' + f(g / 1000, 3) + ' kg × ' + d + ' cm = ' + f(kc, 2) + ' kg·cm; × 0.0981 = ' + f(Nm, 3) + ' N·m.' }; },
    m4ciclorob: rnd => { const nm = pick(rnd, [4, 6, 8]), tm = pick(rnd, [0.4, 0.5, 0.6, 0.8, 1, 1.2]), tp = pick(rnd, [0.2, 0.3, 0.5]), c = nm * tm + 2 * tp, ph = Math.floor(3600 / c + 1e-9), P = x => x + ' piezas por hora';
      return { q: 'Un tomar y dejar tiene ' + nm + ' movimientos de ' + f(tm, 1) + ' s cada uno y dos esperas de pinza de ' + f(tp, 1) + ' s. ¿Cuántas piezas por hora hace, sin paros?', op: ops(P(ph), [P(Math.floor(3600 / (nm * tm))), P(Math.floor(60 / c)), P(Math.floor(3600 / (nm * tm + tp)))], [P(ph * 2), P(Math.floor(ph / 2))]), r: 'Ciclo = ' + nm + ' × ' + f(tm, 1) + ' + 2 × ' + f(tp, 1) + ' = ' + f(c, 2) + ' s; 3600 / ' + f(c, 2) + ' = ' + f(3600 / c, 1) + ' → ' + P(ph) + ' completas.' }; }
  };
